interface PostUcenterPresetApplyD {
  sn: string;
  data: {
    presetId: string;
    serial: number;
    /** 2: PGM, 4: PVW, 0:Auto(切换器为 PVW，拼接器、控制器为 PGM) */
    targetRegion: number;
    /** 辅助信息 */
    auxiliary: {
      /** 加载场景时候携带的kf信息 */
      keyFrame: {
        /** 加载场景时是否执行关键帧：0，执行，1，不执行 */
        enable: 0 | 1;
      };
      /** 场景指定加载的目标屏幕列表 */
      screens?: { guid: string }[];
      /** 加载场景take特效 */
      switchEffect?: {
        type: number;
        time: number;
      };
      swapEnable?: number; // 0: swap未启用，1: swap启用
      effect?: {
        enable: 0 | 1; // 0: 执行特效，1: 不执行特效
      };
    };
  };
}
